cicada 1
title "Keep my title"
// authored track
track bass acid { cutoff = 723.25Hz } // preserve this
pattern p acid { 1 . 5 . }
// scene annotation
instrument voice-b {
  param brightness = 850Hz
  param resonance = 0.2
  param width = 0.43
  param attack = 12ms
  param decay = 550ms
  param sustain = 0.65
  param release = 180ms
  voice poly {
    let tone = (saw(pitch) + pulse(pitch * 1.003, width)) * 0.5
    let amp = adsr(gate, attack, decay, sustain, release)
    let bite = adsr(gate, 9ms, 320ms, 0.18, 160ms)
    out = svf(tone, brightness * exp2(bite * (1.7 + velocity)), resonance) * amp * (0.45 + velocity * 0.55) * 0.065
  }
}

